{
  "county_id": "HVA91",
  "actions": [
    {
      "action_id": "timed-pathways",
      "action": "Åland adopts standardised, timed cancer pathways with a fast-track referral from primary care, following the Danish and Swedish model.",
      "rationale": "The brief recommends timed pathways for Åland and the portfolio scenario estimates 1.4 deaths postponed per year (range 0.2-2.8) at an assumed cost of EUR 46,254 a year, with the action staying in 94% of sensitivity runs.",
      "owner_role": "Wellbeing services county, coordinated nationally by FICAN.",
      "indicator": "Patients waiting over 6 months during the year for access to specialised health care per 10 000 inhabitants.",
      "roadmap_measure": "3.1.2"
    },
    {
      "action_id": "pathway-timestamps",
      "action": "Åland adds first contact, referral, diagnosis and first treatment dates, plus entry route, to the national cancer quality register and publishes county-level medians quarterly.",
      "rationale": "The brief states that time from referral to diagnosis and from diagnosis to first treatment is not published by county, so the Goal 3 indicator cannot be checked from open data for Åland.",
      "owner_role": "FICAN with THL and the Finnish Cancer Registry.",
      "indicator": "Share of new cancer cases with all four timestamps recorded.",
      "roadmap_measure": "3.2.1"
    },
    {
      "action_id": "equal-fast-lane",
      "action": "Åland provides same-week physician assessment and direct-access diagnostics for red-flag symptoms in public health centres, regardless of employment or insurance.",
      "rationale": "The brief shows no measured pathway stage where Åland is clearly worse than the country, so the equal-fast-lane action targets the unmeasured primary-care delay that the DLBCL cohort evidence associates with longer symptom-to-treatment intervals.",
      "owner_role": "Wellbeing services county primary care.",
      "indicator": "Waiting time for elective outpatient medical visit (physician) in primary health care exceeds 7 days from assessment of the need for treatment, % appointments kept.",
      "roadmap_measure": "2.5.2"
    }
  ],
  "evidence_does_not_support": "The evidence does not support that any of these actions will postpone deaths in Åland: the timed-pathways estimate is a model scenario under stated assumptions, the DLBCL route gap is observational from one cancer type, and the timestamps action has no modelled health effect."
}

